import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.userData.handlers = {};

  const srcRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = srcRect.w / srcRect.h;
  const planeW = 2.4;
  const planeH = planeW / aspect;

  const geo = new THREE.PlaneGeometry(planeW, planeH);
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1.0,
    side: THREE.DoubleSide,
    toneMapped: false
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.renderOrder = 2;
  group.add(mesh);

  const cleanups = [];
  let texRef = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      const img = tex.image;
      const aw = (img && img.width) ? img.width : srcRect.w;
      const ah = (img && img.height) ? img.height : srcRect.h;
      const t = tex.clone();
      t.offset.set(srcRect.x / aw, 1.0 - (srcRect.y + srcRect.h) / ah);
      t.repeat.set(srcRect.w / aw, srcRect.h / ah);
      t.center.set(0, 0);
      t.needsUpdate = true;
      mat.map = t;
      mat.needsUpdate = true;
      texRef = t;
    });
  }

  // Idle breathing — one slow transform per design doctrine.
  const idleTL = gsap.timeline({ repeat: -1, yoyo: true });
  idleTL.to(mesh.scale, {
    x: 1.03,
    y: 1.03,
    duration: 2.6,
    ease: 'sine.inOut'
  });
  cleanups.push(() => idleTL.kill());

  // Subtle entrance rise-in (no translate beyond 0.4u).
  mesh.position.y = 0.18;
  mesh.materialOpacityFade = 0;
  const enterTL = gsap.timeline();
  enterTL.to(mesh.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  enterTL.to(mesh, { materialOpacityFade: 1, duration: 0.6, ease: 'power2.out' }, 0);
  cleanups.push(() => enterTL.kill());

  group.userData.cleanup = () => {
    cleanups.forEach((c) => { try { c(); } catch (e) {} });
    geo.dispose();
    mat.dispose();
    if (texRef && texRef.dispose) texRef.dispose();
  };

  return group;
}
